head.script:
scwin.createWindow = function() {
    var ws_s = "<span class=\"sp11\">";
    var ws_m = "subTitle";
    var ws_e = "</span>";
    var c_cnt = 2;
    var c_subName = "spa_css_SKT-577_(WSQ-1157)_sub";
    var c_xmlName = ".xml";
    for (var i = 1; i <= c_cnt; i++) {
        // createWindow = function(title, iconUrl, src , windowTitle , windowId ,openAction, closeAction, windowTooltip, windowHeaderHTML)
        var windowHeaderHTML = ws_s + ws_m + i + ws_e;
        windowContainer1.createWindow(c_subName + i, null, c_subName + i + c_xmlName, null, null, "existWindow",
            null, null, windowHeaderHTML);
    }
}
scwin.setMenu = function(dataArr) {
    /*
     * @description nameLayerMenu 속성 사용시에 메뉴목록을 동적으로 설정합니다. 
     * @param       <Array:Y> arrData 메뉴목록을 설정할 array 데이터
     * @param       <Number:N> height 메뉴의 높이값  
     */
    windowContainer1.setMenu(dataArr, dataArr.length * 21);
}
scwin.windowContainer1_onmenuopen = function(windowId) {
    if (windowContainer1.isMultiView()) {
        scwin.setMenu(["화면 닫기", "듀얼 모니터로 보기", "단일 뷰로 보기", "공유하기"]);
    } else {
        if (windowId === windowContainer1.getSelectedWindowId()) {
            scwin.setMenu(["화면 닫기", "듀얼 모니터로 보기", "공유하기"]);
        } else {
            scwin.setMenu(["화면 닫기", "듀얼 모니터로 보기", "멀티 뷰로 보기", "공유하기"]);
        }
    }
}
scwin.windowContainer1_onmenuclick = function(windowId, selectedItem) {
    switch (selectedItem) {
        case "화면 닫기":
            windowContainer1.closeWindow(windowId);
            break;
        case "듀얼 모니터로 보기":
            // 듀얼모니터로 보도록 함수 붙이면 됨.
            break;
        case "멀티 뷰로 보기":
            windowContainer1.setMultiView(windowId);
            break;
        case "단일 뷰로 보기":
            windowContainer1.setSingleView(windowId);
            break;
        case "공유하기":
            // 공유하기 관련 로직 작성
            break;
    }
}
scwin.doInit = function() {
    this.createWindow();
    this.setMenu(["화면 닫기", "듀얼 모니터로 보기", "멀티 뷰로 보기", "공유하기"]);
    windowContainer1.doCloseAll();
}
scwin.trigger1_onclick = function() {
    scwin.createWindow();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.doInit();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
